module tb;
    // Declare inputs as regs, outputs as wires
    reg clk;
    reg reset;
    wire [3:0] q;

    // Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Stimulus & self-checking:
    integer errors = 0;
    initial begin
        // Test reset functionality
        reset = 1;
        #10;
        if (q !== 4'b0001) begin
            errors = errors + 1;
        end
        reset = 0;

        // Test counting from 1 to 10
        for (int i = 0; i < 10; i++) begin
            #10;
            if (q !== i + 1) begin
                errors = errors + 1;
            end
        end

        // Test counting from 10 to 1
        for (int i = 10; i > 0; i--) begin
            #10;
            if (q !== i) begin
                errors = errors + 1;
            end
        end

        // Test counting from 1 to 10 with reset in between
        reset = 1;
        #10;
        reset = 0;
        for (int i = 0; i < 10; i++) begin
            #10;
            if (q !== i + 1) begin
                errors = errors + 1;
            end
        end

        // Test counting from 10 to 1 with reset in between
        reset = 1;
        #10;
        reset = 0;
        for (int i = 10; i > 0; i--) begin
            #10;
            if (q !== i) begin
                errors = errors + 1;
            end
        end

        // Test counting with clk stuck at 0
        clk = 0;
        #100;
        if (q !== 4'b0001) begin
            errors = errors + 1;
        end

        // Test counting with clk stuck at 1
        clk = 1;
        #100;
        if (q !== 4'b1000) begin
            errors = errors + 1;
        end

        // Test counting with clk stuck at 1 and reset in between
        clk = 1;
        #10;
        reset = 1;
        #10;
        reset = 0;
        #100;
        if (q !== 4'b0001) begin
            errors = errors + 1;
        end

        // Test counting with clk stuck at 1 and reset in between
        clk = 1;
        #10;
        reset = 1;
        #10;
        reset = 0;
        #100;
        if (q !== 4'b1000) begin
            errors = errors + 1;
        end

        // Print test result
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

    // Clock generation
    initial begin
        clk = 0;
        forever begin
            #5;
            clk = !clk;
        end
    end

endmodule

