module tb;
    // Declare inputs as regs, outputs as wires
    reg clk;
    reg reset;
    wire [3:0] q;

    // Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Stimulus & self-checking:
    integer errors = 0;
    initial begin
        // Apply stimulus
        clk = 0;
        reset = 0;
        #10;

        // Test reset functionality
        reset = 1;
        #20;
        if (q !== 4'h1) begin
            errors = errors + 1;
        end
        reset = 0;

        // Test counting functionality
        for (int i = 0; i < 10; i++) begin
            #10;
            if (q !== $signed({i, i, i, i})) begin
                errors = errors + 1;
            end
        end

        // Test overflow
        #10;
        if (q !== 4'h9) begin
            errors = errors + 1;
        end

        // Test reset functionality again
        reset = 1;
        #20;
        if (q !== 4'h1) begin
            errors = errors + 1;
        end

        // Print test result
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        // Terminate simulation
        $finish;
    end
endmodule

