module TopModule (
    input clk,
    input reset,
    input slowena,
    output reg [3:0] q
);

    reg [3:0] counter;
    reg [1:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 4'b0000;
            state <= 2'b00;
        end else begin
            case (state)
                2'b00: begin
                    if (slowena) begin
                        counter <= counter + 1'b1;
                    end
                    state <= 2'b01;
                end
                2'b01: begin
                    if (slowena) begin
                        counter <= counter + 1'b1;
                    end
                    state <= 2'b10;
                end
                2'b10: begin
                    if (slowena) begin
                        counter <= counter + 1'b1;
                    end
                    state <= 2'b11;
                end
                2'b11: begin
                    if (slowena) begin
                        counter <= counter + 1'b1;
                    end
                    state <= 2'b00;
                end
                default: state <= 2'b00;
            endcase
        end
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q <= 4'b0000;
        end else begin
            q <= counter;
        end
    end

endmodule

