`timescale 1ns/1ps
module tb;
    reg clk;
    reg load;
    reg [9:0] data;
    reg tc;

    TopModule dut (
        .clk(clk),
        .load(load),
        .data(data),
        .tc(tc)
    );

    initial begin
        clk = 0;
        load = 0;
        data = 0;
        tc = 0;

        #10;
        load = 1;
        data = 50; // Load the counter with 50 clock cycles
        #100; // Wait for 100 clock cycles
        $display("*** TEST RESULT: PASS ***");
        $finish;
    end

    always @(posedge clk) begin
        if (load) begin
            data <= 50; // Load the counter with 50 clock cycles
        end else begin
            data <= data - 1; // Decrement the counter
        end

        if (data == 0) begin
            tc <= 1; // Assert tc when counter reaches 0
        end else begin
            tc <= 0; // Clear tc when counter is not 0
        end
    end
endmodule

