test_code:
`timescale 1ns/1ps
module tb;
  reg clk;
  reg load;
  reg [9:0] data;
  wire tc;

  TopModule dut (
    .clk(clk),
    .load(load),
    .data(data),
    .tc(tc)
  );

  initial begin
    clk = 0;
    #10;
    forever #5 clk = ~clk;
  end

  initial begin
    $display("Starting testbench");
    data = 10'd10;
    load = 1;
    #10;
    load = 0;
    #20;
    assert (!tc) $display("PASS: tc should be 0 after 20 cycles");
    data = 10'd5;
    load = 1;
    #10;
    load = 0;
    #30;
    assert (tc) $display("PASS: tc should be 1 after 30 cycles");
    $display("*** TEST RESULT: PASS ***");
    $finish;
  end
endmodule

