        load = 0;
        #10;
        if (tc !== 1) begin
            errors = errors + 1;
        end

        // Test 2: Load counter with 0 clock cycles
        load = 1;
        data = 0;
        #10;
        load = 0;
        #10;
        if (tc !== 1) begin
            errors = errors + 1;
        end

        // Test 3: Load counter with 20 clock cycles
        load = 1;
        data = 20;
        #10;
        load = 0;
        #20;
        if (tc !== 0) begin
            errors = errors + 1;
        end

        // Test 4: Load counter with 10 clock cycles, then load again
        load = 1;
        data = 10;
        #10;
        load = 0;
        #10;
        load = 1;
        data = 10;
        #10;
        load = 0;
        #10;
        if (tc !== 0) begin
            errors = errors + 1;
        end

        // Test 5: Load counter with 10 clock cycles, then load again with 0 clock cycles
        load = 1;
        data = 10;
        #10;
        load = 0;
        #10;
        load = 1;
        data = 0;
        #10;
        load = 0;
        #10;
        if (tc !== 0) begin
            errors = errors + 1;
        end

        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
