    TopModule dut (
        .clk(clk),
        .reset(reset),
        .slowena(slowena),
        .q(q)
    );

    // Stimulus
    initial begin
        // Initialize signals
        clk = 0;
        reset = 0;
        slowena = 0;

        // Wait for 10 cycles before starting the test
        #10;

        // Reset the counter
        reset = 1;
        #10;
        reset = 0;

        // Start the test
        slowena = 1;
        #10;

        // Check the initial state
        assert (q == 0);

        // Test the counter
        for (int i = 0; i < 10; i++) begin
            #10;
            assert (q == i);
        end

        // Stop the counter
        slowena = 0;
        #10;

        // Check the final state
        assert (q == 9);

        // Clean up
        $finish;
    end

endmodule

